<?php require __DIR__.'/includes/bootstrap.php'; require_guest(); $pageTitle='Login'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$password=(string)($_POST['password']??''); if(!$email||$password==='')$error='Enter a valid email and password.';else{$s=db()->prepare('SELECT * FROM users WHERE email=? AND is_active=1 LIMIT 1');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($password,$u['password_hash'])){if(password_needs_rehash($u['password_hash'],PASSWORD_DEFAULT)){db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$u['id']]);}login_user($u);redirect('dashboard.php');}else{$error='Email or password is incorrect.';}}} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login · Sticky Order Dashboard</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="panel auth"><h1>Sign in</h1><p class="muted">Access your brand order reports.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="field"><label>Email</label><input type="email" name="email" required autocomplete="username" value="<?=e($_POST['email']??'')?>"></div><div class="field"><label>Password</label><input type="password" name="password" required autocomplete="current-password"></div><button type="submit">Login</button></form><p><a href="forgot_password.php">Forgot password?</a></p></main></body></html>